def max_increasing_subsequence(n, a):
    dp = [[0, ''], [0, '']]
    for x in a:
        new_dp = [[0, ''], [0, '']]
        for i in range(2):
            if dp[i][0] == 0 or (dp[i][0] > 0 and dp[i][1][-1] < str(x)):
                new_dp[i][0] = dp[i][0] + 1
                new_dp[i][1] = dp[i][1] + ('L' if i == 0 else 'R')
        dp = new_dp
    return max(dp, key=lambda x: x[0])

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:]))
    k, s = max_increasing_subsequence(n, a)
    print(k)
    print(s)

if __name__ == "__main__":
    solve()
